  const overviewBudgets=sorted(data.budgets.filter((budget)=>budget.period===selectedMonth),'budget',{category:(b)=>get('categories',b.categoryId)?.name,plan:(b)=>money(b.amount),spent:(b)=>periodTransactions().filter((t)=>t.categoryId===b.categoryId&&t.type==='expense').reduce((sum,t)=>sum+money(t.amount),0n)}).slice(0,overviewLimit('Budgets'));
  if(overviewBudgets.length)previewCards.push(card(`<div class="section-head">${overviewCardTitle('Budget progress','How spending compares with your plan')}${viewAll('#/budget')}</div>${overviewBudgets.map((budget)=>{const spent=periodTransactions().filter((t)=>t.categoryId===budget.categoryId&&t.type==='expense').reduce((sum,t)=>sum+money(t.amount),0n),state=budgetProgress(budget.amount,decimal(spent),budget.warning),category=get('categories',budget.categoryId);return overviewProgressRow({title:category?.name||'Category',meta:`${fmt(spent)} spent of ${amt(budget.amount)}`,value:Number(state.used)/100,amount:pct(state.used),status:state.status,cls:'budget-row'});}).join('')}`));
  const overviewGoals=sorted(data.goals.filter((goal)=>!goal.archived),'goals',{priority:(goal)=>({high:1,medium:2,low:3}[goal.priority]||4),progress:(goal)=>goalProjection(goal.current,goal.target,goal.monthly).completion}).slice(0,overviewLimit('Goals'));
