  const categoryRows=data.categories.map((category)=>({name:category.name,total:expenses.filter((transaction)=>transaction.categoryId===category.id).reduce((sum,transaction)=>sum+money(transaction.amount),0n)})).filter((category)=>category.total).sort((a,b)=>compare(b.total,a.total));
