  const budgeted=data.budgets.filter((budget)=>budget.period===selectedMonth).reduce((sum,budget)=>sum+money(budget.amount),0n),variance=budgeted-cf.expenses,maxTrend=history.reduce((maximum,item)=>item.income>maximum?item.income:maximum,history.reduce((maximum,item)=>item.expenses>maximum?item.expenses:maximum,1n));
