function loansTable() { const rows=sorted(data.loans,'loans',{balance:(loan)=>money(loan.balance),annualRate:(loan)=>money(loan.annualRate),monthlyPayment:(loan)=>money(loan.monthlyPayment)});if(!rows.length)return empty('loans');return `<div class="table-wrap"><table><thead><tr><th>${sortButton('loans','name','Loan')}</th><th>${sortButton('loans','balance','Balance')}</th><th>${sortButton('loans','annualRate','Interest rate')}</th><th>${sortButton('loans','monthlyPayment','Monthly payment')}</th><th>Payments left</th><th>Projected interest</th><th><span class="visually-hidden">Actions</span></th></tr></thead><tbody>${rows.map((loan)=>{let result;try{result=amortize({principal:loan.balance,annualRate:loan.annualRate,monthlyPayment:loan.monthlyPayment,extraPayment:loan.extraPayment});}catch{result={schedule:[],totalInterest:0n};}return `<tr><td><strong>${esc(loan.name)}</strong><div class="item-meta">${esc(loan.lender)}</div><div class="responsive-mobile-meta">${esc(loan.lender)} · ${esc(loan.annualRate)}% · ${result.schedule.length} payments left</div></td><td class="amount">${amt(loan.balance)}</td><td>${esc(loan.annualRate)}% ${esc(loan.interestType)}</td><td class="amount">${amt(loan.monthlyPayment)}</td><td>${result.schedule.length}</td><td class="amount expense">${fmt(result.totalInterest)}</td><td>${overflowMenu('loans',loan.id,loan.name)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function loans() { return `<div class="toolbar responsive-sort-toolbar"><div class="responsive-sort">${sortSelect('loans',[['name','Name'],['balance','Balance'],['annualRate','Interest rate'],['monthlyPayment','Monthly payment']])}</div></div>${card(loansTable(),'list-surface responsive-table-card loans-card')}`; }
function settings() { const s=data.settings; return `<form id="settings-form" class="settings-grid">${card(`<div class="section-head"><h2>General</h2></div>${field('Locale','locale','text',s.locale)}${field('Time zone','timezone','text',s.timezone)}`)}${card(`<div class="section-head"><h2>Financial period</h2></div><div class="field"><label for="f-monthStart">Financial month starts (1–28)</label><input id="f-monthStart" name="monthStart" type="number" min="1" max="28" step="1" value="${esc(s.monthStart)}" required></div><p class="small muted">With day 25, August covers July 25 through August 24.</p>`)}${card(`<div class="section-head"><h2>Currency & appearance</h2></div>${field('Primary currency','primaryCurrency','select',s.primaryCurrency,s.currencies.map(c=>[c,c]))}${field('Theme','theme','select',s.theme,[['system','System'],['light','Light'],['dark','Dark']])}`)}${card(`<div class="section-head"><h2>Budget defaults</h2></div><div class="field"><label for="f-budgetWarning">Warning threshold (%)</label><input id="f-budgetWarning" name="budgetWarning" type="number" min="1" max="100" step="1" value="${esc(s.budgetWarning)}" required></div>`)}${card(`<div class="section-head"><div><h2>Overview previews</h2><span class="small muted">Entries shown per section</span></div></div><div class="overview-limit-grid">${overviewLimitField('Financial insights','Insights')}${overviewLimitField('Spending categories','Spending')}${overviewLimitField('Budget progress','Budgets')}${overviewLimitField('Goals','Goals')}${overviewLimitField('Upcoming bills','Bills')}</div>`,'overview-settings-card')}<div class="settings-save"><span class="small muted" id="settings-status" aria-live="polite">Changes are saved to MySQL.</span><button class="button primary">Save preferences</button></div></form><div class="grid two-col settings-secondary">${card(`<div class="section-head"><h2>Dashboard widgets</h2></div><div class="list">${Object.entries(summaryMetrics()).map(([key,value])=>`<label class="list-item"><input type="checkbox" data-widget="${key}" ${data.widgets.includes(key)?'checked':''}><span>${esc(value[0])}</span></label>`).join('')}</div>`)}${card(`<div class="section-head"><h2>Categories</h2><button class="button" data-add="categories">＋ Add</button></div>${data.categories.map(c=>`<div class="list-item"><span class="avatar" style="color:${esc(c.color)}">${esc(c.icon)}</span><div><div class="item-title">${esc(c.name)}</div><div class="item-meta">${esc(c.type)}</div></div><button class="button small" data-edit="categories" data-id="${c.id}">Edit</button></div>`).join('')}`)}${card(`<div class="section-head"><h2>Data & privacy</h2></div><div class="callout">Financial records are stored in your connected MySQL database.</div><div class="actions" style="margin-top:16px"><button class="button" data-action="demo">Restore demo</button><button class="button danger" data-action="clear">Clear data</button></div>`)}</div>`; }
function assistantAnswer(question) { const q=question.toLowerCase(),cf=cashFlow(periodTransactions()),history=monthlyHistory(),previous=history.at(-2),expenses=periodTransactions().filter(t=>t.type==='expense'&&t.status!=='pending'),categories=data.categories.map(c=>({name:c.name,total:expenses.filter(t=>t.categoryId===c.id).reduce((s,t)=>s+money(t.amount),0n)})).sort((a,b)=>compare(b.total,a.total)),top=categories[0];if(q.includes('save')||q.includes('forecast')){const monthly=cf.income-cf.expenses;return monthly>0n?`At this period's pace, you retain ${fmt(monthly)} per month and about ${fmt(monthly*12n)} over 12 months, before interest or one-off changes.`:`This period has a ${fmt(-monthly)} shortfall. A positive savings forecast requires reducing expenses or increasing cleared income.`;}if(q.includes('increase')||q.includes('compare'))return previous?`Expenses are ${fmt(cf.expenses)} this period versus ${fmt(previous.expenses)} in ${previous.label}, a change of ${pct(periodChange(cf.expenses,previous.expenses).percent)}.`:'There is not enough prior-period activity for a reliable comparison.';if(q.includes('category')||q.includes('spend')||q.includes('expense'))return top&&top.total>0n?`${top.name} is your largest expense category this period at ${fmt(top.total)}, representing ${pct(ratio(top.total,cf.expenses))} of cleared expenses.`:'No cleared expenses were recorded in this financial period.';if(q.includes('bill')){const open=data.bills.filter(b=>!b.paid);return open.length?`${open.length} bill${open.length===1?' is':'s are'} open, totaling ${fmt(open.reduce((s,b)=>s+money(b.amount),0n))}. The next due date is ${open.sort((a,b)=>a.dueDate.localeCompare(b.dueDate))[0].dueDate}.`:'All recorded bills are marked paid.';}return `For ${periodLabel()}, cleared income is ${fmt(cf.income)}, expenses are ${fmt(cf.expenses)}, and the savings rate is ${pct(savingsRateMinor(cf))}. Try asking about spending, comparisons, bills, or savings forecasts.`; }
const ollamaUrl = () => String(data.settings.ollamaUrl||'http://192.168.0.133:11434').replace(/\/+$/,'');
const ollamaModel = () => String(data.settings.ollamaModel||'qwen3:4b');
function assistantContext() { const flow=cashFlow(periodTransactions());return {period:periodLabel(),range:periodBounds(),currency:data.settings.primaryCurrency,income:decimal(flow.income),expenses:decimal(flow.expenses),remaining:decimal(flow.income-flow.expenses),transactions:periodTransactions().map((transaction)=>({date:transaction.date,description:transaction.description,merchant:transaction.merchant,amount:transaction.amount,currency:transaction.currency,type:transaction.type,category:get('categories',transaction.categoryId)?.name||'Uncategorized',status:transaction.status})),budgets:data.budgets.filter((budget)=>budget.period===selectedMonth).map((budget)=>({category:get('categories',budget.categoryId)?.name||'Category',amount:budget.amount})),openBills:data.bills.filter((bill)=>!bill.paid).map((bill)=>({name:bill.name,amount:bill.amount,currency:bill.currency,dueDate:bill.dueDate})),goals:data.goals.filter((goal)=>!goal.archived).map((goal)=>({name:goal.name,target:goal.target,current:goal.current,monthly:goal.monthly}))}; }
async function askOllama(prompt) { const response=await fetch('/api/ai/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseUrl:ollamaUrl(),model:ollamaModel(),prompt})});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.message||'Could not reach Ollama');}return (await response.json()).content; }
const evaluationCacheKey = () => `${new Date().toISOString().slice(0,10)}|${selectedMonth}|${ollamaUrl()}|${ollamaModel()}`;
async function refreshAssistantEvaluation(force=false) { const key=evaluationCacheKey(),cached=data.settings.aiEvaluation;if(!force&&cached?.key===key)return;if(assistantEvaluationLoading||(!force&&assistantEvaluationAttempt===key))return;assistantEvaluationAttempt=key;assistantEvaluationLoading=true;assistantEvaluationError='';const startedAt=performance.now();try{const content=await askOllama(`You are a concise personal finance analyst. Evaluate the current financial month using only the JSON data supplied. Return plain text in this exact structure: a one-line headline, then at most four short bullet points beginning with •. Mention material risks, budget pressure, savings pace, and upcoming bills only when supported. Do not invent facts.\n\nDATA:\n${JSON.stringify(assistantContext())}`);data.settings.aiEvaluation={key,content,generatedAt:new Date().toISOString(),durationMs:Math.round(performance.now()-startedAt),model:ollamaModel()};await repo.save(data);}catch(error){assistantEvaluationError=error.message;}finally{assistantEvaluationLoading=false;if(route()==='assistant')render();} }
async function askAssistant(question) { assistantQuestion=question.trim();if(!assistantQuestion)return;assistantLoading=true;assistantResponse='';render();try{assistantResponse=await askOllama(`Answer the user's personal-finance question using only the supplied JSON data. Be concise, factual, and explicit when the data is insufficient. Do not provide professional financial advice.\n\nQUESTION: ${assistantQuestion}\n\nDATA:\n${JSON.stringify(assistantContext())}`);}catch(error){assistantResponse=`Ollama is unavailable (${error.message}). Local calculation: ${assistantAnswer(assistantQuestion)}`;}finally{assistantLoading=false;render();} }
function assistant() { const cf=cashFlow(periodTransactions()),forecast=cf.income-cf.expenses,evaluation=data.settings.aiEvaluation?.key===evaluationCacheKey()?data.settings.aiEvaluation:null,evaluationText=evaluation?.content||(assistantEvaluationError?`Ollama is unavailable: ${assistantEvaluationError}`:'Preparing today’s evaluation…'),runDetails=evaluation?`Run ${new Intl.DateTimeFormat(data.settings.locale,{dateStyle:'medium',timeStyle:'short'}).format(new Date(evaluation.generatedAt))} · ${(evaluation.durationMs/1000).toFixed(1)} seconds`:'Runs once daily when this page is opened';return `<div class="assistant-hero"><div><span class="badge healthy">Local Ollama · ${esc(ollamaModel())}</span><h2>Your financial copilot</h2><p>Analysis runs through your configured Ollama server at ${esc(ollamaUrl())}.</p></div><div class="assistant-forecast"><span>12-month savings forecast</span><strong class="${forecast<0n?'expense':'income'}">${fmt(forecast*12n)}</strong><small>Based on this period's cleared cash flow</small></div></div><div class="grid assistant-grid">${card(`<div class="section-head"><div><h2>Daily evaluation</h2><span class="small muted">${esc(runDetails)}</span></div><button class="button small" data-action="refresh-ai" ${assistantEvaluationLoading?'disabled':''}>${assistantEvaluationLoading?'Refreshing…':'Refresh'}</button></div><div class="ai-evaluation" aria-live="polite">${esc(evaluationText)}</div>`,'ai-evaluation-card')}${card(`<div class="section-head"><h2>Ask Quiet Ledger</h2></div><form id="assistant-form"><label for="assistant-question">Question about your finances</label><div class="assistant-input"><input id="assistant-question" name="question" value="${esc(assistantQuestion)}" placeholder="Where did my spending increase?" required><button class="button primary" ${assistantLoading?'disabled':''}>${assistantLoading?'Thinking…':'Ask'}</button></div></form>${assistantLoading?`<div class="assistant-answer" aria-live="polite"><span class="avatar">Q</span><p>Asking ${esc(ollamaModel())}…</p></div>`:assistantResponse?`<div class="assistant-answer" aria-live="polite"><span class="avatar">Q</span><p>${esc(assistantResponse)}</p></div>`:`<div class="question-chips"><button data-action="assistant-prompt" data-question="Where did my spending increase?">Compare spending</button><button data-action="assistant-prompt" data-question="How much can I save?">Forecast savings</button><button data-action="assistant-prompt" data-question="What bills are due?">Review bills</button></div>`}`)}</div>`; }
function renderPage(page) { return ({overview,accounts,transactions:transactionsPage,budget:budgetPage,bills,goals,investments,'net-worth':netWorthPage,reports,calendar,loans,settings,assistant}[page] || overview)(); }

const forms = {
  accounts: (x={}) => `${field('Account name','name','text',x.name)}${field('Institution','institution','text',x.institution)}${field('Type','type','select',x.type||'current',[['current','Current'],['savings','Savings'],['cash','Cash'],['credit-card','Credit card'],['fixed-deposit','Fixed deposit'],['investment','Investment'],['loan','Loan'],['mortgage','Mortgage'],['vehicle-loan','Vehicle loan'],['wallet','Digital wallet'],['other-asset','Other asset'],['other-liability','Other liability']])}${field('Group','group','select',x.group||'asset',[['asset','Asset'],['liability','Liability']])}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Balance','balance','number',x.balance||'0.00')}${field('Masked number','mask','text',x.mask||'•••• 0000')}${field('Colour','color','color',x.color||'#635bff')}<div class="field span-2"><label><input type="checkbox" name="includeNetWorth" ${x.includeNetWorth!==false?'checked':''}> Include in net worth</label></div>`,
  transactions: (x={}) => `${field('Date','date','date',x.date||`${selectedMonth}-01`)}${field('Description','description','text',x.description)}${field('Merchant','merchant','text',x.merchant)}${field('Amount','amount','number',x.amount||'0.00')}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Type','type','select',x.type||'expense',[['income','Income'],['expense','Expense'],['transfer','Transfer'],['refund','Refund']])}${field('Account','accountId','select',x.accountId||'',data.accounts.map(a=>[a.id,a.name]))}${field('Category','categoryId','select',x.categoryId||'',[['','Uncategorized'],...data.categories.map(c=>[c.id,c.name])])}${field('Status','status','select',x.status||'cleared',[['cleared','Cleared'],['pending','Pending'],['reconciled','Reconciled']])}`,
  budgets: (x={}) => `${field('Category','categoryId','select',x.categoryId||'',data.categories.filter(c=>c.type==='expense').map(c=>[c.id,c.name]))}${field('Budget amount','amount','number',x.amount||'0.00')}${field('Period','period','month',x.period||selectedMonth)}${field('Method','method','select',x.method||'standard',[['standard','Non-rollover'],['rollover','Rollover'],['zero-based','Zero-based']])}${field('Warning threshold %','warning','number',x.warning||data.settings.budgetWarning)}`,
  bills: (x={}) => `${field('Bill name','name','text',x.name)}${field('Payee','payee','text',x.payee)}${field('Amount','amount','number',x.amount||'0.00')}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Frequency','frequency','select',x.frequency||'monthly',[['weekly','Weekly'],['biweekly','Every two weeks'],['monthly','Monthly'],['bimonthly','Every two months'],['quarterly','Quarterly'],['semiannual','Every six months'],['annual','Annually'],['custom','Custom']])}${field('Due date','dueDate','date',x.dueDate||new Date().toISOString().slice(0,10))}${field('Account','accountId','select',x.accountId||'',data.accounts.map(a=>[a.id,a.name]))}${field('Category','categoryId','select',x.categoryId||'',[['','Uncategorized'],...data.categories.filter(c=>c.type==='expense').map(c=>[c.id,c.name])])}${field('Reminder days','reminder','number',x.reminder||3)}<div class="field"><label><input type="checkbox" name="autopay" ${x.autopay?'checked':''}> Auto-pay</label></div>`,
  goals: (x={}) => `${field('Goal name','name','text',x.name)}${field('Description','description','text',x.description)}${field('Target amount','target','number',x.target||'0.00')}${field('Current saved','current','number',x.current||'0.00')}${field('Monthly contribution','monthly','number',x.monthly||'0.00')}${field('Target date','targetDate','date',x.targetDate||new Date().toISOString().slice(0,10))}${field('Priority','priority','select',x.priority||'medium',[['low','Low'],['medium','Medium'],['high','High']])}${field('Colour','color','color',x.color||'#635bff')}`,
  holdings: (x={}) => `${field('Name','name','text',x.name)}${field('Symbol','symbol','text',x.symbol)}${field('Asset class','assetClass','text',x.assetClass)}${field('Quantity','quantity','number',x.quantity||'0.00')}${field('Average cost','averageCost','number',x.averageCost||'0.00')}${field('Current price','currentPrice','number',x.currentPrice||'0.00')}${field('Currency','currency','select',x.currency||data.settings.primaryCurrency,data.settings.currencies.map(c=>[c,c]))}${field('Dividends','dividends','number',x.dividends||'0.00')}`,
  loans: (x={}) => `${field('Loan name','name','text',x.name)}${field('Lender','lender','text',x.lender)}${field('Original principal','principal','number',x.principal||'0.00')}${field('Current balance','balance','number',x.balance||'0.00')}${field('Annual interest %','annualRate','number',x.annualRate||'0')}${field('Monthly payment','monthlyPayment','number',x.monthlyPayment||'0.00')}${field('Extra payment','extraPayment','number',x.extraPayment||'0.00')}${field('Interest type','interestType','select',x.interestType||'reducing',[['reducing','Reducing balance'],['flat','Flat']])}`,
  categories: (x={}) => `${field('Category name','name','text',x.name)}${field('Type','type','select',x.type||'expense',[['expense','Expense'],['income','Income']])}${field('Icon','icon','text',x.icon||'○')}${field('Colour','color','color',x.color||'#635bff')}${field('SMS matching keywords','smsKeywords','text',Array.isArray(x.smsKeywords)?x.smsKeywords.join(', '):(x.smsKeywords||''))}`
};
function modal(resource,id='',defaults={}) { const existing=id?get(resource,id):defaults; const label=resource[0].toUpperCase()+resource.slice(1,-1); document.body.insertAdjacentHTML('beforeend',`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><section class="modal-card"><div class="section-head"><h2 id="modal-title">${id?'Edit':'Add'} ${esc(label)}</h2><button class="button icon-button" data-close aria-label="Close">×</button></div>${defaults.importSource === 'banking-sms' ? '<div class="callout">Review the parsed details before saving. The SMS was processed locally.</div>' : ''}<form id="entity-form" data-resource="${resource}" data-id="${id}" class="form-grid">${forms[resource](existing)}${defaults.rawSms ? `<input type="hidden" name="rawSms" value="${esc(defaults.rawSms)}"><input type="hidden" name="importSource" value="banking-sms">` : ''}<div class="actions span-2"><button class="button primary" type="submit">Save</button>${id?'<button class="button danger" type="button" data-delete>Delete</button>':''}<button class="button" type="button" data-close>Cancel</button></div></form></section></div>`); document.querySelector('.modal input:not([type="hidden"])')?.focus(); }
async function smsModal() { let clipboard=''; try { clipboard=await navigator.clipboard?.readText() || ''; } catch { clipboard=''; } document.body.insertAdjacentHTML('beforeend',`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="sms-title"><section class="modal-card"><div class="section-head"><div><h2 id="sms-title">Import banking SMS</h2><span class="small muted">Parsed privately in your browser</span></div><button class="button icon-button" data-close aria-label="Close">×</button></div><form id="sms-form"><div class="field"><label for="banking-sms">Online banking message</label><textarea id="banking-sms" name="sms" rows="7" maxlength="2000" placeholder="Paste a debit or credit notification…" required>${esc(clipboard)}</textarea></div><div class="callout" style="margin-top:14px">No message content is sent to a bank or AI service. Verify the amount, account, and category on the next screen.</div><div class="actions" style="margin-top:18px"><button class="button primary" type="submit">Analyze SMS</button><button class="button" type="button" data-close>Cancel</button></div></form></section></div>`); document.querySelector('#banking-sms').focus(); }
function formValues(form) { const values=Object.fromEntries(new FormData(form)); form.querySelectorAll('input[type=checkbox]').forEach(i=>values[i.name]=i.checked); return values; }
function moveMonth(offset) { const [year,month]=selectedMonth.split('-').map(Number); const next=new Date(Date.UTC(year,month-1+offset,1)); selectedMonth=next.toISOString().slice(0,7); sessionStorage.setItem('harbor-finance-period',selectedMonth); render(); }
function generateHistoricalBudget() { const periods=Array.from({length:12},(_,index)=>reportingMonthOffset(selectedMonth,-index-1)).filter((period)=>transactionsForMonth(period).some((t)=>t.type==='expense'&&t.status!=='pending'));if(!periods.length){toast('Add expense history before generating a budget');return;}const existing=new Set(data.budgets.filter((budget)=>budget.period===selectedMonth).map((budget)=>budget.categoryId)),weights=periods.map((_,index)=>periods.length-index),weightTotal=BigInt(weights.reduce((sum,weight)=>sum+weight,0));const suggestions=data.categories.filter((category)=>category.type==='expense'&&!existing.has(category.id)).map((category)=>{const totals=periods.map((period)=>transactionsForMonth(period).filter((t)=>t.type==='expense'&&t.status!=='pending'&&t.categoryId===category.id).reduce((sum,t)=>sum+money(t.amount),0n)),weighted=totals.reduce((sum,total,index)=>sum+total*BigInt(weights[index]),0n);return {categoryId:category.id,amount:(weighted/weightTotal+99n)/100n*100n};}).filter((suggestion)=>suggestion.amount>0n).map((suggestion)=>({id:`budg-${uniqueId()}`,categoryId:suggestion.categoryId,amount:decimal(suggestion.amount),period:selectedMonth,method:'standard',warning:data.settings.budgetWarning}));if(!suggestions.length){toast(`${periodLabel()} already covers all categories with spending history`);return;}data.budgets=[...data.budgets,...suggestions];repo.save(data);render();toast(`${suggestions.length} suggested budget${suggestions.length===1?'':'s'} created from ${periods.length} historical period${periods.length===1?'':'s'}`); }
function postBillOccurrence(bill,dueDate) { const existing=data.transactions.some((transaction)=>transaction.billId===bill.id&&transaction.billDueDate===dueDate);if(existing)return false;data.transactions.push({id:`tran-${uniqueId()}`,date:dueDate,description:bill.name,merchant:bill.payee||bill.name,amount:bill.amount,currency:bill.currency||data.settings.primaryCurrency,type:'expense',accountId:bill.accountId||'',categoryId:bill.categoryId||'',status:'cleared',billId:bill.id,billDueDate:dueDate});return true; }
function settleBill(bill) { const dueDate=bill.dueDate,created=postBillOccurrence(bill,dueDate);bill.dueDate=nextOccurrence(dueDate,bill.frequency);bill.paid=false;repo.save(data);return created; }
function processDueAutopayBills() { const today=new Date().toISOString().slice(0,10);let changed=false;for(const bill of data.bills.filter((item)=>item.autopay&&!item.paid)){let occurrences=0;while(bill.dueDate<=today&&occurrences<120){changed=postBillOccurrence(bill,bill.dueDate)||changed;bill.dueDate=nextOccurrence(bill.dueDate,bill.frequency);occurrences+=1;changed=true;}}if(changed)repo.save(data); }
function mountAiSettings() { const form=document.querySelector('#settings-form');if(!form)return;form.insertAdjacentHTML('afterbegin',card(`<div class="section-head"><div><h2>Local AI</h2><span class="small muted">Ollama connection</span></div></div>${field('Ollama URL','ollamaUrl','url',ollamaUrl())}${field('Model','ollamaModel','text',ollamaModel())}<p class="small muted">Daily analysis runs when the AI Assistant page is first opened each day.</p>`,'ollama-settings-card')); }
function render() { data=repo.load();processDueAutopayBills();applyTheme();shell(route());mountAiSettings();if(route()==='assistant'&&!data.settings.aiEvaluation){const status=document.querySelector('.ai-evaluation-card .small.muted'),body=document.querySelector('.ai-evaluation');if(status)status.textContent='Scheduled daily from 5:00 AM';if(body)body.textContent='The first automatic analysis will run early in the morning. Use Refresh to run it now.';}requestAnimationFrame(()=>{const trend=document.querySelector('.trend-chart-scroll');if(trend)trend.scrollLeft=trend.scrollWidth;}); }

document.addEventListener('submit',async(event)=>{if(event.target.id!=='assistant-form')return;event.preventDefault();event.stopImmediatePropagation();await askAssistant(String(new FormData(event.target).get('question')||''));},true);
document.addEventListener('click',async(event)=>{const target=event.target.closest('[data-action="assistant-prompt"],[data-action="refresh-ai"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();if(target.dataset.action==='assistant-prompt')await askAssistant(target.dataset.question);else await refreshAssistantEvaluation(true);},true);

document.addEventListener('submit',(event)=>{ event.preventDefault(); const form=event.target;
  try { if(form.id==='assistant-form'){assistantQuestion=String(new FormData(form).get('question')||'').trim();render();return;}if(form.id==='sms-form'){const parsed=parseBankingSms(new FormData(form).get('sms'),{accounts:data.accounts,categories:data.categories,primaryCurrency:data.settings.primaryCurrency});form.closest('.modal').remove();modal('transactions','',parsed);return;} if(form.id==='entity-form'){const values=formValues(form); ['amount','balance','target','current','monthly','principal','monthlyPayment','extraPayment','averageCost','currentPrice','dividends','quantity'].forEach(k=>{if(k in values) money(values[k]);}); const resource=form.dataset.resource,id=form.dataset.id; if(resource==='accounts'){values.archived=false;values.updatedAt=new Date().toISOString();} if(resource==='categories') values.smsKeywords=String(values.smsKeywords||'').split(',').map((value)=>value.trim()).filter(Boolean); if(resource==='bills') values.paid=get(resource,id)?.paid||false; if(resource==='goals'){values.archived=false;values.icon=get(resource,id)?.icon||'◎';values.type=get(resource,id)?.type||'custom';} id?repo.update(resource,id,values):repo.create(resource,values); document.querySelector('.modal').remove(); render(); toast(`${resource.slice(0,-1)} saved`); return;} if(form.id==='settings-form'){const v=formValues(form),monthStart=Number(v.monthStart),budgetWarning=Number(v.budgetWarning),limitKeys=['Insights','Spending','Budgets','Goals','Bills'];financialPeriod(selectedMonth,monthStart);if(!Number.isInteger(budgetWarning)||budgetWarning<1||budgetWarning>100) throw new Error('Warning threshold must be from 1 to 100.');limitKeys.forEach((key)=>{const name=`overview${key}Limit`,value=Number(v[name]);if(!Number.isInteger(value)||value<1||value>10)throw new Error('Overview entry limits must be from 1 to 10.');v[name]=value;});data.settings={...data.settings,...v,monthStart,budgetWarning};repo.save(data);render();toast('Preferences saved');} } catch(error){toast(error.message);} });
document.addEventListener('click',(event)=>{const target=event.target.closest('[data-action],[data-add],[data-edit],[data-close],[data-delete],[data-sort-page],[data-list-direction]');if(!target)return;
  if(target.dataset.sortPage){const page=target.dataset.sortPage,state=sortState[page];state.direction=state.key===target.dataset.sortKey?(state.direction==='asc'?'desc':'asc'):'asc';state.key=target.dataset.sortKey;if(page in listPages)listPages[page]=1;render();return;} if(target.dataset.listDirection){const page=target.dataset.listDirection,state=sortState[page];state.direction=state.direction==='asc'?'desc':'asc';if(page in listPages)listPages[page]=1;render();return;}
  if(target.dataset.close!==undefined){target.closest('.modal').remove();return;} if(target.dataset.add){target.closest('details')?.removeAttribute('open');const defaults=target.dataset.add==='transactions'&&target.dataset.transactionType?{type:target.dataset.transactionType}:{};modal(target.dataset.add,'',defaults);return;} if(target.dataset.edit){target.closest('details')?.removeAttribute('open');modal(target.dataset.edit,target.dataset.id);return;} if(target.dataset.delete!==undefined){const form=target.closest('form');if(confirm('Delete this record? This cannot be undone.')){repo.remove(form.dataset.resource,form.dataset.id);target.closest('.modal').remove();render();}return;}
  const action=target.dataset.action;if(action==='previous-month')moveMonth(-1); if(action==='next-month')moveMonth(1); if(action==='current-month'){selectedMonth=new Date().toISOString().slice(0,7);sessionStorage.setItem('harbor-finance-period',selectedMonth);render();} if(action==='list-page'){listPages[target.dataset.listPage]=Number(target.dataset.page);render();} if(action==='sms-import'){target.closest('details')?.removeAttribute('open');smsModal();} if(action==='pay-bill'){const bill=get('bills',target.dataset.id),created=settleBill(bill);render();toast(created?'Bill posted to transactions':'Bill occurrence was already posted');} if(action==='skip-bill'){const bill=get('bills',target.dataset.id);repo.update('bills',bill.id,{dueDate:nextOccurrence(bill.dueDate,bill.frequency),paid:false});render();toast('Bill moved to its next due date');}if(action==='assistant-prompt'){assistantQuestion=target.dataset.question;render();} if(action==='demo'&&confirm('Replace current data with removable demo data?')){repo.clear(true);render();} if(action==='clear'&&confirm('Delete all financial data? This cannot be undone.')){repo.clear(false);render();} if(action==='generate-budget')generateHistoricalBudget();
});
document.addEventListener('click',(event)=>{document.querySelectorAll('.action-menu[open],.overflow-menu[open],.quick-add[open]').forEach((menu)=>{if(!menu.contains(event.target))menu.removeAttribute('open');});});
document.addEventListener('keydown',(event)=>{if(event.key==='Escape')document.querySelectorAll('details[open]').forEach((menu)=>menu.removeAttribute('open'));});
document.addEventListener('input',(event)=>{if(event.target.id==='search'){search=event.target.value;document.querySelector('.transactions-card').innerHTML=transactionTable(filteredTransactions());} if(event.target.dataset.widget){const key=event.target.dataset.widget;data.widgets=event.target.checked?[...new Set([...data.widgets,key])]:data.widgets.filter(x=>x!==key);repo.save(data);}});
document.addEventListener('change',(event)=>{if(event.target.dataset.listSort){const page=event.target.dataset.listSort;sortState[page].key=event.target.value;if(page in listPages)listPages[page]=1;render();} if(event.target.dataset.listPageSize!==undefined){listPageSize=Number(event.target.value);Object.keys(listPages).forEach((page)=>listPages[page]=1);render();} if(event.target.id==='period-month'&&/^\d{4}-\d{2}$/.test(event.target.value)){selectedMonth=event.target.value;sessionStorage.setItem('harbor-finance-period',selectedMonth);render();}});
window.addEventListener('hashchange',render); repo.subscribe((next)=>{data=next;}); render();
